/* Global Reset & Base Styling */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

:root {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --card-border: #334155;
  --text-primary: #f8fafc;
  --text-muted: #94a3b8;
  --accent: #38bdf8;
  --error-bg: #ef4444;
  --error-text: #ffffff;
  --swatch-border: #475569;
  --font-stack: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

body {
  font-family: var(--font-stack);
  font-size: 16px;
  line-height: 1.5;
  background-color: var(--bg-color);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem 1rem;
}

.converter-card {
  background-color: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 1rem;
  padding: 2rem;
  width: 100%;
  max-width: 440px;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.card-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
  color: var(--text-primary);
}

.card-header p {
  font-size: 1rem;
  color: var(--text-muted);
}

.channel-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.input-group label {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
}

.input-group input {
  font-family: inherit;
  font-size: 1.125rem;
  padding: 0.75rem 1rem;
  border-radius: 0.5rem;
  border: 2px solid var(--card-border);
  background-color: #0f172a;
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  width: 100%;
}

.input-group input:hover {
  border-color: #475569;
}

.input-group input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.25);
}

.input-group input.is-invalid {
  border-color: var(--error-bg);
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.25);
}

.preview-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.25rem;
  padding-top: 0.5rem;
}

.swatch {
  width: 100%;
  height: 110px;
  border-radius: 0.75rem;
  border: 2px solid var(--swatch-border);
  background-color: #ff8800;
  transition: background-color 0.15s ease, opacity 0.15s ease;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.2);
}

.swatch.disabled {
  background-color: #334155 !important;
  opacity: 0.6;
}

.output-display {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
}

.output-label {
  font-size: 0.8125rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.hex-value {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--text-primary);
}

.error-banner {
  width: 100%;
  text-align: center;
  background-color: rgba(239, 68, 68, 0.15);
  border: 1px solid var(--error-bg);
  color: #fca5a5;
  font-weight: 600;
  padding: 0.65rem 1rem;
  border-radius: 0.5rem;
}

document.addEventListener("DOMContentLoaded", () => {
  const redInput = document.getElementById("red-input");
  const greenInput = document.getElementById("green-input");
  const blueInput = document.getElementById("blue-input");
  const swatch = document.getElementById("color-swatch");
  const hexOutput = document.getElementById("hex-output");
  const errorMessage = document.getElementById("error-message");

  const inputs = [redInput, greenInput, blueInput];

  function isValidChannel(val) {
    if (val === "" || val === null || val === undefined) return false;
    const trimmed = String(val).trim();
    if (!/^\d+$/.test(trimmed)) return false;
    const num = Number(trimmed);
    return num >= 0 && num <= 255;
  }

  function toHex(channelValue) {
    const hex = Number(channelValue).toString(16).toUpperCase();
    return hex.padStart(2, "0");
  }

  function updateConverter() {
    let allValid = true;

    inputs.forEach((input) => {
      const valid = isValidChannel(input.value);
      if (!valid) {
        allValid = false;
        input.classList.add("is-invalid");
      } else {
        input.classList.remove("is-invalid");
      }
    });

    if (allValid) {
      const r = Number(redInput.value.trim());
      const g = Number(greenInput.value.trim());
      const b = Number(blueInput.value.trim());
      const hex = `#${toHex(r)}${toHex(g)}${toHex(b)}`;

      hexOutput.textContent = hex;
      swatch.setAttribute("style.background-color", hex);
      swatch.style.backgroundColor = hex;
      swatch.classList.remove("disabled");
      errorMessage.hidden = true;
    } else {
      hexOutput.textContent = "------";
      swatch.removeAttribute("style.background-color");
      swatch.classList.add("disabled");
      errorMessage.textContent = "Invalid value";
      errorMessage.hidden = false;
    }
  }

  inputs.forEach((input) => {
    input.addEventListener("input", updateConverter);
    input.addEventListener("change", updateConverter);
  });

  updateConverter();
});
